from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Step 1: Remove spaces from the input string
    extracted_groups = []  # Step 2: Initialize an empty list to store extracted groups

    open_count = 0
    group_start = 0

    for i, char in enumerate(paren_string):
        if char == '(':
            open_count += 1
            if open_count == 1:
                group_start = i
        elif char == ')':
            open_count -= 1
            if open_count == 0:
                extracted_groups.append(paren_string[group_start:i+1])  # Step 5: Extract and append each group to the list

    return extracted_groups  # Step 6: Return the list of extracted groups

